(()=>{'use strict';const B=MartinsPainelObra,J=MartinsJornada,P=MartinsPersistenciaRdo,$=id=>document.getElementById(id);if(!$('view-gestao'))return;
const panel=document.createElement('section');panel.id='subview-equipe-obra';panel.className='mf-box hidden';panel.innerHTML='<h3>Equipe e Planejamento da Obra</h3><p>Compara fontes existentes. Planejar não registra presença, aprova RDO ou gera despesa. Horas planejadas, realizadas e documentadas são mostradas separadamente.</p><div class="mf-grid"><label>Data de referência<input id="po-day" type="date"></label><label>Período<select id="po-period"><option value="dia">Dia</option><option value="semana">Semana</option><option value="mes">Mês</option></select></label></div><button id="po-refresh" type="button">Atualizar equipe da obra</button><button id="po-plan" type="button">Abrir Planejamento desta obra</button><button id="po-csv" type="button">Exportar equipe CSV</button><p id="po-summary" role="status"></p><p id="po-costs"></p><p id="po-message" role="status"></p><div class="mf-scroll"><table><thead><tr><th>Dia</th><th>Colaborador / vínculo / equipe</th><th>Planejado</th><th>Frequência</th><th>RDO aprovado / rascunho</th><th>Conferência / distribuição</th></tr></thead><tbody id="po-rows"></tbody></table></div>';$('subview-gastos-obra')?.after(panel);if(!panel.isConnected)$('view-gestao').append(panel);
const tab=document.createElement('button');tab.id='subtab-btn-equipe-obra';tab.type='button';tab.className='subtab-btn px-3 py-1.5 text-xs font-medium text-slate-600 rounded-md';tab.textContent='Equipe e Planejamento';$('subtab-btn-gastos')?.after(tab);
const style=document.createElement('style');style.textContent='#subview-equipe-obra h3{font-weight:800}#subview-equipe-obra button{min-height:44px;padding:10px;margin:5px;border-radius:8px;background:#0f172a;color:#fbbf24}#subview-equipe-obra th,#subview-equipe-obra td{padding:10px;vertical-align:top;text-align:left;white-space:normal;overflow-wrap:anywhere;border-bottom:1px solid #cbd5e1}#subview-equipe-obra table{width:100%;min-width:960px}#subview-equipe-obra th:first-child,#subview-equipe-obra td:first-child{min-width:110px;white-space:nowrap}#subview-equipe-obra th:nth-child(2),#subview-equipe-obra td:nth-child(2){min-width:190px}#subview-equipe-obra th:nth-child(3),#subview-equipe-obra th:nth-child(4),#subview-equipe-obra td:nth-child(3),#subview-equipe-obra td:nth-child(4){min-width:95px;white-space:nowrap}#subview-equipe-obra p{white-space:pre-wrap;margin:10px 0}#subtab-btn-equipe-obra{min-height:44px}@media(max-width:600px){#subview-equipe-obra .mf-grid{grid-template-columns:1fr}#subview-equipe-obra button{width:100%;margin:5px 0}}';document.head.append(style);
let current=null,url=null;
function authorized(){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!u||u.status==='Inativo'||!session||id(u)!==id(session)||session.perfil!==u.perfil||session.status==='Inativo'||u.permissoes?.gestao===false||!(u.perfil==='Master'||u.permissoes?.gestao===true||/Engenharia|Responsável Técnica|Diretoria|Administrativo|Recursos Humanos/.test(u.perfil||'')))throw Error('Entre com perfil autorizado à Gestão da Obra');return u;}
function render(){current=null;$('po-rows').replaceChildren();$('po-summary').textContent='';$('po-costs').textContent='';try{const user=authorized(),work=$('gestao-obra-select').value,read=(key,fallback)=>J.read(localStorage,key,fallback),canCosts=MartinsFinanceiro.canReadWork(user),sources={plans:read(J.KEYS.plans,[]),frequency:read(J.KEYS.frequency,initialFrequenciaDb),rdos:read(J.KEYS.rdos,initialRdos),employees:read('cm_colaboradores_db',initialColaboradores),works:read('cm_dados_obras_v2',dadosObras),config:MartinsPlanejamento.config(localStorage),ledger:canCosts?read(MartinsGastosObras.KEY,[]):[]},r=B.report(sources,work,$('po-day').value,$('po-period').value,{includeCosts:canCosts});current=r;$('po-summary').textContent=work+' · '+r.inicio.split('-').reverse().join('/')+' a '+r.fim.split('-').reverse().join('/')+' · '+r.colaboradores+' colaborador(es) · Planejado '+r.totals.planejado+'h · Frequência '+r.totals.frequencia+'h · RDO aprovado '+r.totals.rdoAprovado+'h · Rascunho '+r.totals.rdoRascunho+'h';const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});$('po-costs').textContent=r.costs?'Despesas vinculadas à obra por data de lançamento: pagas '+money(r.costs.pago)+' · pendentes '+money(r.costs.pendente)+' · canceladas (fora do ativo) '+money(r.costs.cancelado)+'. Não soma estimativas do planejamento.':'Custos financeiros disponíveis somente aos perfis autorizados.';for(const x of r.rows){const tr=document.createElement('tr');for(const value of [x.data.split('-').reverse().join('/'),x.nome+' / '+x.vinculo+(x.equipes.length?' / '+x.equipes.join('; '):''),x.planejado+'h',x.frequencia+'h',x.rdoAprovado+'h / '+x.rdoRascunho+'h',[x.situacao,...x.issues,...x.outrasObrasPlanejadas.map(w=>'Planejado também: '+w),...x.outrasObrasRealizadas.map(w=>'Frequência também: '+w.obra+' '+w.horas+'h')].join('; ')]){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('po-rows').append(tr);}if(!r.rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.textContent='Sem equipe registrada nas fontes desta obra e período.';tr.append(td);$('po-rows').append(tr);}$('po-message').textContent=r.warnings.join('\n');}catch(e){$('po-message').textContent=e.message;}}
const old=window.setSubtabGestao;window.setSubtabGestao=function(name){old?.(name);panel.classList.toggle('hidden',name!=='equipe-obra');tab.setAttribute('aria-pressed',String(name==='equipe-obra'));if(name==='equipe-obra')render();};tab.onclick=()=>window.setSubtabGestao('equipe-obra');tab.parentElement?.addEventListener('click',e=>{const b=e.target.closest('.subtab-btn');if(b&&b!==tab)panel.classList.add('hidden');});
$('po-day').value=P.brDay();$('po-refresh').onclick=render;$('po-period').onchange=render;$('po-day').onchange=render;$('gestao-obra-select')?.addEventListener('change',()=>{if(!panel.classList.contains('hidden'))render();});
$('po-plan').onclick=()=>{try{authorized();const work=$('gestao-obra-select').value;if(!$('mj-dialog').open)$('mj-open')?.click();if(!$('mj-work')||![...$('mj-work').options].some(o=>o.value===work))throw Error('Abra o Planejamento e confira o cadastro desta obra');$('mj-work').value=work;$('mj-day').value=$('po-day').value;$('mj-day').dispatchEvent(new Event('change'));if(!$('mj-dialog').open)$('mj-dialog').showModal();$('mp-panel').open=true;}catch(e){$('po-message').textContent=e.message;}};
$('po-csv').onclick=()=>{try{authorized();render();if(!current)return;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([B.csv(current)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='martins-equipe-obra.csv';a.click();}catch(e){$('po-message').textContent=e.message;}};
window.addEventListener('storage',e=>{if([J.KEYS.plans,J.KEYS.frequency,J.KEYS.rdos,'cm_colaboradores_db','cm_dados_obras_v2',MartinsPlanejamento.KEY,MartinsGastosObras.KEY].includes(e.key)&&!panel.classList.contains('hidden'))render();});window.martinsFormatarDatas?.();
})();
